int main(int argc,char**argv){if(argc!=3)return 2;@autoreleasepool{s_dev=MTLCreateSystemDefaultDevice();if(!s_dev)return 2;s_queue=[s_dev newCommandQueue];NSError*error=nil;s_eng_helper_lib=[s_dev newLibraryWithSource:kEngHelperMSL options:nil error:&error];CHECK(s_eng_helper_lib!=nil,"production helper library");
