 size_t n=k==0?16:k==1?8:k==2?4:2;const void*want=k==0||k==2?(const void*)words:(const void*)halves;[src replaceRegion:MTLRegionMake2D(0,0,1,1) mipmapLevel:0 withBytes:want bytesPerRow:n];u32 h=eng_obj_add(src);char p[2048],raw[2100];snprintf(p,sizeof p,"%s/f%u.rgba",argv[1],k);snprintf(raw,sizeof raw,"%s.raw",p);CHECK(eng_capture_texture_rgba8(NULL,h,p),"existing converted capture completes");CHECK(s_eng_rec_count==0,"prior records completed before physical readback");u8 got[16];size_t z=readfile(raw,got,16);if(strcmp(argv[2],"1")==0){CHECK(z==n,"raw sidecar has exact physical byte count");CHECK(z==n&&memcmp(got,want,n)==0,"float storage bits survive conversion and view swizzle");}else CHECK(z==0,"disabled raw capture adds no sidecar");}
 const float clear[4]={.25f,.5f,.75f,1.0f};u32 produced=eng_color_target_create(NULL,RSX_BE_FMT_R32G32B32A32F,1,1,NULL,0);CHECK(produced!=0,"float render target");eng_clear_color(NULL,produced,clear);CHECK(s_eng_rec_count==1,"prior GPU producer pending");char p[2048],raw[2100];snprintf(p,sizeof p,"%s/produced.rgba",argv[1]);snprintf(raw,sizeof raw,"%s.raw",p);CHECK(eng_capture_texture_rgba8(NULL,produced,p),"GPU-produced float capture completes");CHECK(s_eng_rec_count==0,"GPU producer records drained");u8 got[16];size_t z=readfile(raw,got,16);if(strcmp(argv[2],"1")==0)CHECK(z==16&&!memcmp(got,clear,16),"GPU-produced original float bits preserved");else CHECK(z==0,"disabled GPU-produced raw adds nothing");
